__NUXT_JSONP__("/inclusion/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{columnas:[{slug:"mas_alla_de_la_emergencia_la_crisis_climatica_tiene_rostro_de_mujer",title:"Más allá de la emergencia: la crisis climática tiene rostro de mujer",date:"2026-06-24T18:23:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fd8c85187-1f97-4d86-8a67-f920a97deecf\u002F","img-alt":"Mujeres crisis climática",autor:f,medio:d,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Femergencia-crisis-climatica-mujer",category:a,extracto:"La gestión de riesgos de desastres no puede seguir operando bajo un enfoque asistencialista o neutro. Necesitamos una metamorfosis radical: desde políticas que aseguren la titularidad de la tierra y la redistribución del cuidado, hasta una representación femenina real en la toma de decisiones climáticas.",toc:[{id:"el-mito-de-la-igualdad",depth:e,text:"El mito de la igualdad"},{id:"el-desastre-las-golpea-sobre-todo-a-ellas",depth:e,text:"El desastre las golpea sobre todo a ellas"},{id:"urge-una-metamorfosis-radical",depth:e,text:"Urge una metamorfosis radical"}],dir:b,path:"\u002Fcolumnas\u002Fmas_alla_de_la_emergencia_la_crisis_climatica_tiene_rostro_de_mujer",extension:c,createdAt:g,updatedAt:g},{slug:"colision_de_derechos-_vivienda_y_propiedad_en_la_ciudad_de_mexico",title:"Colisión de derechos. Vivienda y propiedad en la Ciudad de México",date:"2026-05-07T16:07:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fec25e174-eeef-4111-bf7a-adb1f861d78b\u002F-\u002Fcrop\u002F390x259\u002F0,0\u002F-\u002Fpreview\u002F","img-alt":"Vivienda CDMX",autor:"Emiliano Montes de Oca",medio:"Expansión",link:"https:\u002F\u002Fobras.expansion.mx\u002Fopinion\u002F2026\u002F05\u002F07\u002Fcolision-de-derechos-vivienda-y-propiedad-en-la-ciudad-de-mexico",category:a,extracto:"El derecho a la vivienda no puede entenderse como una autorización para ocupar indefinidamente un inmueble sin contraprestación. Pero tampoco el derecho de propiedad puede ejercerse de manera irrestricta, ignorando la vulnerabilidad de quienes rentan un inmueble, señala Emiliano Montes de Oca.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fcolision_de_derechos-_vivienda_y_propiedad_en_la_ciudad_de_mexico",extension:c,createdAt:h,updatedAt:h},{slug:"de_la_emergencia_a_la_resiliencia_lo_que_falta_en_mexico",title:"De la emergencia a la resiliencia: lo que falta en México",date:"2026-04-14T21:56:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F8ad1f0bd-11ae-4488-981c-0b069d9c8bf8\u002F","img-alt":"Desastres perspectiva de género",autor:"Liliana Alvarado ",medio:"El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Femergencia-resiliencia-falta-mexico-20260414-808611.html",category:a,extracto:"México enfrenta huracanes cada vez más intensos por el cambio climático, evidenciando la necesidad de mejorar prevención, respuesta, recuperación y enfoque de género en la gestión de desastres.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fde_la_emergencia_a_la_resiliencia_lo_que_falta_en_mexico",extension:c,createdAt:i,updatedAt:i},{slug:"el_espejismo_de_la_igualdad_por_que_las_mujeres_siguen_alejadas_de_la_ciencia_y_como_cambiarlo",title:"El espejismo de la igualdad: por qué las mujeres siguen alejadas de la ciencia y cómo cambiarlo",date:"2026-04-09T15:29:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fd2dfdefc-b5b7-4a40-be71-ee768b25a165\u002F","img-alt":"Mujeres en la ciencia",autor:f,medio:d,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Fbrecha-genero-stem-mexico-mujeres",category:a,extracto:"Las múltiples barreras educativas, junto con el techo de cristal impuesto por la estructura socioeconómica, explican que en México apenas tres de cada diez personas profesionistas en carreras de Ciencia, Tecnología, Ingeniería y Matemáticas (STEM) sean mujeres.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fel_espejismo_de_la_igualdad_por_que_las_mujeres_siguen_alejadas_de_la_ciencia_y_como_cambiarlo",extension:c,createdAt:j,updatedAt:j},{slug:"sin_perspectiva_de_genero_la_reforma_de_plataformas_digitales_esta_incompleta",title:"Sin perspectiva de género, la reforma de plataformas digitales está incompleta",date:"2026-02-12T16:23:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F2f285ff7-5d78-4a7a-8036-0e5a070df21c\u002F","img-alt":"Trabajadoras de plataformas digitales",autor:k,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fsin-perspectiva-de-genero-reforma-plataformas-digitales-incompleta",category:a,extracto:"Si bien los números globales del programa piloto del IMSS para trabajadores de plataformas digitales son alentadores, un análisis más profundo nos revela que el diseño actual de la reforma corre el riesgo de dejar atrás a una parte vital del gremio: las mujeres.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fsin_perspectiva_de_genero_la_reforma_de_plataformas_digitales_esta_incompleta",extension:c,createdAt:"2026-07-19T00:56:17.197Z",updatedAt:"2026-07-19T00:56:17.198Z"},{slug:"sembrando_el_cambio_en_el_papel_el_reto_de_materializar_el_trabajo_justo_en_el_campo",title:"Sembrando el cambio ¿en el papel? El reto de materializar el trabajo justo en el campo",date:"2025-12-05T16:11:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F6a051299-66a0-4b1c-a1e5-99213b917abc\u002F","img-alt":"Trabajadoras agrícolas",autor:k,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fmaterializar-trabajo-justo-en-campo",category:a,extracto:"La agenda para un trabajo justo está trazada, pero requiere acción contundente y coordinada de todas las dependencias federales y locales. No basta con que la ley exista en el papel, es urgente fortalecer la inspección con perspectiva de género, asegurar la afiliación real al IMSS, erradicar la práctica simulada de los “pases” de salud, y ampliar y adaptar los servicios de guardería a los ciclos agrícolas y a las jornadas de trabajo reales.",toc:[{id:"el-contrato-invisible-y-la-falsa-promesa",depth:e,text:"El contrato invisible y la falsa promesa"},{id:"la-ausencia-del-estado-en-la-vigilancia-laboral",depth:e,text:"La ausencia del Estado en la vigilancia laboral"},{id:"sembrar-el-cambio-una-tarea-urgente",depth:e,text:"Sembrar el cambio, una tarea urgente"}],dir:b,path:"\u002Fcolumnas\u002Fsembrando_el_cambio_en_el_papel_el_reto_de_materializar_el_trabajo_justo_en_el_campo",extension:c,createdAt:l,updatedAt:l},{slug:"disaster_management_with_a_gender_perspective_a_historic_debt",title:"Disaster Management with a Gender Perspective: A Historic Debt",date:"2025-10-14T17:31:01.093Z",img:"https:\u002F\u002Fucarecdn.com\u002F24099e07-6fee-4e29-aea4-f6ecf79ee239\u002F","img-alt":"Manejo de desastres naturales",autor:"Néstor Genis y Luisa Crespi",medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fgestion-desastres-perspectiva-genero-deuda-pendiente",category:a,extracto:"Disasters disproportionately affect vulnerable groups, and women face a double burden: beyond the immediate crisis, they shoulder the majority of domestic and care work, protecting children, the elderly, and the sick. During and after emergencies, they manage scarce resources, search for water and food, and lead emotional and material reconstruction efforts.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fdisaster_management_with_a_gender_perspective_a_historic_debt",extension:c,createdAt:"2025-11-25T01:24:03.235Z",updatedAt:"2025-11-25T01:24:03.236Z"},{slug:"la_persistente_brecha_salarial_de_genero_en_mexico",title:"La persistente brecha salarial de género en México",date:"2025-10-02T18:23:15.144Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd83edafc-5d49-426e-8b1d-d078246767ce\u002F",autor:f,medio:d,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fla-persistente-brecha-salarial-de-genero-en-mexico",category:a,extracto:"Cerrar la brecha salarial de género es un asunto de justicia social, una necesidad económica, una inversión en nuestro futuro y un pilar para construir un México más equitativo y próspero para todas y todos.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_persistente_brecha_salarial_de_genero_en_mexico",extension:c,createdAt:m,updatedAt:m}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("inclusion","\u002Fcolumnas",".md","Animal Político",3,"Mónica Corona","2026-07-19T00:56:17.192Z","2026-07-19T00:56:17.180Z","2026-07-19T00:56:17.181Z","2026-07-19T00:56:17.183Z","Néstor Genis","2026-01-04T19:38:07.810Z","2025-11-25T01:24:03.244Z")));